365	    const trigger = nav.querySelector<HTMLElement>(`[data-flyout-trigger="${activeFlyout}"]`);
366	    if (!panel || !trigger) return;
367	
368	    const position = () => {
369	      const gutter = 24; // 1.5rem
370	      const btn = trigger.getBoundingClientRect();
371	      const width = panel.offsetWidth;
372	      const maxLeft = window.innerWidth - gutter - width;
373	      const left = Math.max(gutter, Math.min(btn.left, maxLeft));
374	      // The sticky <header>'s backdrop-filter makes this fixed panel positioned
375	      // relative to the header, not the viewport. Rather than guess which ancestor
376	      // is the containing block, measure it: park the panel at 0,0 and read where
377	      // that lands, then offset our viewport-space targets by that origin.
378	      panel.style.left = "0px";
379	      panel.style.top = "0px";
380	      const origin = panel.getBoundingClientRect();
381	      panel.style.left = `${left - origin.left}px`;
382	      panel.style.top = `${btn.bottom + 11 - origin.top}px`;
383	    };
384	
385	    position();
386	    window.addEventListener("resize", position);
387	    return () => window.removeEventListener("resize", position);
388	  }, [activeFlyout]);
